with flagged as (select *, case when started_at - lag(started_at) over (partition by customer_id order by started_at, id) > interval 30 days then 1 else 0 end as new_group_flag from sessions), sessionized as (select *, sum(new_group_flag) over (partition by customer_id order by started_at, id rows between unbounded preceding and current row) as session_id from flagged) select id, device, browser, started_at, country, new_group_flag, session_id, case when browser rlike '^(Firefox|Safari)$' then 'EXTENDED' when browser rlike '^(Chrome|Edge)$' then 'OTHER_ZONE' else 'GROUP_A' end as browser_zone from sessionized order by browser nulls first
